import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { IMAGES } from '../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'Inicio', path: '/' },
    { name: 'Quiénes Somos', path: '/about' },
    { name: 'Planes', path: '/plans' },
    { name: 'Profesores', path: '/teachers' },
    { name: 'Experiencias', path: '/experiences' },
  ];

  const isActive = (path: string) => {
    return location.pathname === path ? 'text-rr-blue font-semibold' : 'text-gray-600 hover:text-rr-blue';
  };

  const scrollToContact = () => {
    const contactSection = document.getElementById('contact-section');
    if (contactSection) {
      contactSection.scrollIntoView({ behavior: 'smooth' });
      setIsOpen(false); // Close mobile menu if open
    }
  };

  return (
    <nav className="bg-white shadow-sm sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* CAMBIO: Altura aumentada a h-32 para acomodar el logo gigante */}
        <div className="flex justify-between h-32">
          <div className="flex items-center">
            <Link to="/" className="flex items-center gap-4">
              {/* Logo Image */}
              {/* CAMBIO: Logo aumentado a h-28 */}
              <img 
                src={IMAGES.logo} 
                alt="RR Music Academy" 
                className="h-28 w-auto object-contain"
                onError={(e) => {
                  e.currentTarget.style.display = 'none';
                  e.currentTarget.nextElementSibling?.classList.remove('hidden');
                }}
              />
              {/* Fallback Text ONLY */}
              <span className="hidden text-xs text-red-500 font-bold border border-red-300 border-dashed p-2 rounded bg-red-50">
                FALTA: images/logo.png
              </span>

              {/* SLOGAN */}
              {/* CAMBIO: leading-[0.8] para un interlineado muy compacto */}
              <div className="flex flex-col justify-center space-y-0">
                <span className="font-['Oswald'] text-lg sm:text-xl font-bold text-rr-blue tracking-tight leading-[0.8] uppercase">LIVE, CONNECT,</span>
                <span className="font-['Oswald'] text-lg sm:text-xl font-bold text-rr-blue tracking-tight leading-[0.8] uppercase">AND BREATHE MUSIC</span>
              </div>
            </Link>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-4 lg:space-x-8">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`transition-colors duration-200 text-sm tracking-wide ${isActive(link.path)}`}
              >
                {link.name}
              </Link>
            ))}

            {/* NUEVO BOTÓN: Énfasis sutil para el Director */}
            <Link
                to="/director"
                className={`px-4 py-2 rounded-full border border-rr-blue text-sm font-medium transition-all duration-300 
                  ${location.pathname === '/director' 
                    ? 'bg-blue-50 text-rr-blue shadow-inner' 
                    : 'text-rr-blue bg-transparent hover:bg-blue-50'}`}
            >
                Nuestro Director
            </Link>

            <button 
              onClick={scrollToContact}
              className="bg-rr-blue text-white px-5 py-2 rounded-full text-sm font-medium hover:bg-blue-700 transition-colors shadow-md hover:shadow-lg"
            >
              Inscribirse
            </button>
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-600 hover:text-rr-blue focus:outline-none"
            >
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 absolute w-full shadow-lg">
          <div className="px-4 pt-2 pb-6 space-y-2">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-3 rounded-md text-base font-medium ${
                  location.pathname === link.path
                    ? 'bg-blue-50 text-rr-blue'
                    : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}

            {/* Botón Director Móvil */}
            <Link
                to="/director"
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-3 rounded-md text-base font-medium border border-blue-100 mt-2 ${
                  location.pathname === '/director'
                    ? 'bg-blue-50 text-rr-blue'
                    : 'text-rr-blue bg-white hover:bg-blue-50'
                }`}
            >
                Nuestro Director
            </Link>

            <div className="pt-4">
               <button 
                onClick={scrollToContact}
                className="w-full bg-rr-blue text-white px-5 py-3 rounded-lg text-center font-medium hover:bg-blue-700 transition-colors"
               >
                Inscribirse
              </button>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

