            </Link>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:flex items-center space-x-4 lg:space-x-8">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`transition-colors duration-200 text-sm tracking-wide ${isActive(link.path)}`}
              >
                {link.name}
              </Link>
            ))}

            {/* NUEVO BOTÓN: Énfasis sutil para el Director */}
            <Link
                to="/director"
                className={`px-4 py-2 rounded-full border border-rr-blue text-sm font-medium transition-all duration-300 
                  ${location.pathname === '/director' 
                    ? 'bg-blue-50 text-rr-blue shadow-inner' 
                    : 'text-rr-blue bg-transparent hover:bg-blue-50'}`}
            >
                Nuestro Director
            </Link>

            <button 
              onClick={scrollToContact}
              className="bg-rr-blue text-white px-5 py-2 rounded-full text-sm font-medium hover:bg-blue-700 transition-colors shadow-md hover:shadow-lg"
            >
              Inscribirse
            </button>
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-600 hover:text-rr-blue focus:outline-none"
            >
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 absolute w-full shadow-lg">
          <div className="px-4 pt-2 pb-6 space-y-2">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-3 rounded-md text-base font-medium ${
                  location.pathname === link.path
                    ? 'bg-blue-50 text-rr-blue'
                    : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}

            {/* Botón Director Móvil */}
            <Link
                to="/director"
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-3 rounded-md text-base font-medium border border-blue-100 mt-2 ${
                  location.pathname === '/director'
                    ? 'bg-blue-50 text-rr-blue'
                    : 'text-rr-blue bg-white hover:bg-blue-50'
                }`}
            >
                Nuestro Director
            </Link>

            <div className="pt-4">
               <button 
                onClick={scrollToContact}
                className="w-full bg-rr-blue text-white px-5 py-3 rounded-lg text-center font-medium hover:bg-blue-700 transition-colors"
               >
                Inscribirse
              </button>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

