              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {IMAGES.gallery.map((imgUrl, index) => (
                  <div key={index} className="relative group overflow-hidden rounded-lg aspect-square bg-gray-100 cursor-pointer">
