            <button 
                onClick={toggleCart}
                className="relative p-2 text-gray-600 hover:text-rr-blue transition-colors"
                aria-label="Abrir carrito"
            >
                <ShoppingBag className="w-6 h-6" />
                {cartCount > 0 && (
                    <span className="absolute top-0 right-0 inline-flex items-center justify-center px-1.5 py-0.5 text-xs font-bold leading-none text-white transform translate-x-1/4 -translate-y-1/4 bg-red-500 rounded-full">
                        {cartCount}
                    </span>
                )}
            </button>

            <Link 
                to="/plans"
                className="bg-rr-blue text-white px-6 py-3 rounded-full text-sm font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors shadow-md hover:shadow-lg whitespace-nowrap flex items-center gap-2"
            >
                <Star className="w-4 h-4 fill-white" />
                Ver Planes
            </Link>
          </div>

          {/* Mobile Menu Button & Cart */}
          <div className="md:hidden flex items-center gap-4">
            <button onClick={toggleCart} className="relative text-gray-600">
                 <ShoppingBag className="h-6 w-6" />
                 {cartCount > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">
                        {cartCount}
                    </span>
                 )}
            </button>
            <button onClick={() => setIsOpen(!isOpen)} className="text-gray-600 hover:text-rr-blue focus:outline-none">
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Dropdown */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 absolute w-full shadow-lg h-screen overflow-y-auto pb-20">
          <div className="px-4 pt-2 pb-6 space-y-2">
            {navLinks.map((link) => (
              <Link key={link.path} to={link.path} onClick={() => setIsOpen(false)} className={`block px-3 py-3 rounded-md text-base font-medium ${location.pathname === link.path ? 'bg-blue-50 text-rr-blue' : 'text-gray-600 hover:bg-gray-50'}`}>
                {link.name}
              </Link>
            ))}

            <Link
                to="/director"
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-3 rounded-md text-base font-medium border border-blue-100 mt-2 ${
                  location.pathname === '/director'
                    ? 'bg-blue-50 text-rr-blue'
                    : 'text-rr-blue bg-white hover:bg-blue-50'
                }`}
            >
                Nuestro Director
            </Link>

            <div className="pt-4">
                <Link 
                    to="/plans"
                    onClick={() => setIsOpen(false)}
                    className="block w-full text-center bg-rr-blue text-white px-5 py-3 rounded-lg font-bold hover:bg-blue-700 transition-colors"
                >
                    VER PLANES Y PRECIOS
                </Link>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

